/* KF_TASK1_EXPANSION_200_20261119: 200 new IELTS Writing Task 1 lessons (2025-2026) + native practice translations */
(() => {
  'use strict';
  if (window.KFTask1Expansion200 || /^\/admin-live(?:\.html)?\/?$/.test(location.pathname)) return;
  const B64 = '';
  let dataPromise = null;

  async function loadPack() {
    if (!dataPromise) {
      dataPromise = (async () => {
        const bytes = Uint8Array.from(atob(B64), c => c.charCodeAt(0));
        const text = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
        const parsed = JSON.parse(text);
        const byId = new Map(parsed.lessons.map(l => [l.id, l]));
        const trById = new Map(parsed.translations.map(t => [t.task1Source, t]));
        return { lessons: parsed.lessons, translations: parsed.translations, byId, trById };
      })();
    }
    return dataPromise;
  }

  const metadata = l => ({
    id: l.id,
    title: l.title,
    type: l.type,
    topic: l.topic,
    collection: l.collection,
    level: l.level,
    skill: l.skill,
    prompt: l.prompt,
    wordCount: l.wordCount,
    file: 'task1-bank/lessons/' + l.id + '.json'
  });
  const jsonRes = value => new Response(JSON.stringify(value), {
    status: 200,
    headers: { 'Content-Type': 'application/json;charset=utf-8', 'Cache-Control': 'no-store' }
  });

  const origFetch = window.fetch;
  window.fetch = function (input, options) {
    let u;
    try {
      u = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
    } catch {
      return origFetch.apply(this, arguments);
    }
    const method = String(options?.method || (typeof input === 'object' && input.method) || 'GET').toUpperCase();
    if (method !== 'GET' || u.origin !== location.origin) return origFetch.apply(this, arguments);

    const mLesson = u.pathname.match(/^\/task1-bank\/lessons\/(t1-(?:line|bar|pie|table|mixed|maps|process)-\d{2})\.json$/);
    if (mLesson) {
      return loadPack().then(pack => pack.byId.has(mLesson[1]) ? jsonRes(pack.byId.get(mLesson[1])) : origFetch.apply(this, arguments));
    }

    const mTr = u.pathname.match(/^\/task1-translations\/(t1-(?:line|bar|pie|table|mixed|maps|process)-\d{2})\.json$/);
    if (mTr) {
      return loadPack().then(pack => pack.trById.has(mTr[1]) ? jsonRes(pack.trById.get(mTr[1])) : origFetch.apply(this, arguments));
    }

    if (u.pathname === '/task1-bank/index.json') {
      return Promise.all([origFetch.apply(this, arguments), loadPack()]).then(async ([r, pack]) => {
        if (!r.ok) return r;
        const bank = await r.json();
        if (!Array.isArray(bank.lessons)) return jsonRes(bank);
        const ids = new Set(bank.lessons.map(l => l.id));
        for (const l of pack.lessons) {
          if (!ids.has(l.id)) {
            bank.lessons.push(metadata(l));
            ids.add(l.id);
          }
        }
        bank.collections = Array.isArray(bank.collections) ? bank.collections : [];
        if (!bank.collections.some(c => c.id === 'reported-2025-2026')) {
          bank.collections.unshift({ id: 'reported-2025-2026', name: 'Đề mới 2025–2026 (+200 bài)' });
        }
        return jsonRes(bank);
      });
    }
    return origFetch.apply(this, arguments);
  };

  window.KFTask1Expansion200 = { version: '20261119-task1-200-v1', count: 200, loadPack };

  // If task1-course.js already rendered 300/302 lessons or failed on one of our 200 IDs before fetch hook attached, trigger clean re-render once
  if (/^\/writing\/?$/.test(location.pathname)) {
    const sp = new URLSearchParams(location.search);
    if (sp.get('view') === 'task1') {
      setTimeout(() => {
        const root = document.getElementById('writing-root');
        if (!root || window.__KF_T1_200_REBOOTED__) return;
        const txt = root.textContent || '';
        const t1Id = sp.get('task1') || '';
        const needsReboot = (!t1Id && /30[0-2]\s*ĐỀ/i.test(txt)) || (t1Id && /Chưa mở được bài học|Không tìm thấy bài/i.test(txt));
        if (needsReboot) {
          window.__KF_T1_200_REBOOTED__ = true;
          const sc = document.createElement('script');
          sc.src = 'task1-course.js?v=307-practice-position&kf200=1';
          document.head.appendChild(sc);
        }
      }, 900);
    }
  }
})();
